node -v && node --input-type=module -e '
import { createPushGate } from "./bot.mjs";
const base = { id: "u_8841", timeZone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00", dailyCap: 3 };
const g = createPushGate();
const at = (iso) => new Date(iso);
const out = [];
// Tokyo is UTC+9. 2026-10-23 12:00 local = 03:00Z
out.push(["day allowed", g.attempt(base, at("2026-10-23T03:00:00Z"))]);
out.push(["quiet 23:30 local", g.attempt({...base, id:"q"}, at("2026-10-23T14:30:00Z"))]);
out.push(["quiet start inclusive 22:00", g.attempt({...base, id:"s"}, at("2026-10-23T13:00:00Z"))]);
out.push(["end exclusive 07:00 allowed", g.attempt({...base, id:"e"}, at("2026-10-22T22:00:00Z"))]);
out.push(["end 06:59 quiet", g.attempt({...base, id:"e2"}, at("2026-10-22T21:59:00Z"))]);
out.push(["bad zone", g.attempt({...base, id:"z", timeZone:"Mars/Base"}, at("2026-10-23T03:00:00Z"))]);
out.push(["bad hhmm", g.attempt({...base, id:"h", quietStart:"25:00"}, at("2026-10-23T03:00:00Z"))]);
out.push(["bad cap", g.attempt({...base, id:"c", dailyCap: 1.5}, at("2026-10-23T03:00:00Z"))]);
out.push(["bad now", g.attempt(base, new Date("x"))]);
// cap: 3 allowed on Tokyo day 2026-10-23, 4th refused
const cu = {...base, id:"cap"};
const r = [];
for (const t of ["2026-10-23T01:00:00Z","2026-10-23T03:00:00Z","2026-10-23T05:00:00Z","2026-10-23T06:00:00Z"]) r.push(g.attempt(cu, at(t)).reason ?? "allowed");
out.push(["cap 4 sends same local day", r]);
// next local day resets: 2026-10-24 09:00 Tokyo = 00:00Z
out.push(["next local day allowed", g.attempt(cu, at("2026-10-24T00:00:00Z"))]);
// cap 0 refuses
out.push(["cap 0", g.attempt({...base, id:"z0", dailyCap:0}, at("2026-10-23T03:00:00Z"))]);
// cross-zone: UTC user, same instant, day boundary differs per user
const ny = {id:"ny", timeZone:"America/New_York", quietStart:"22:00", quietEnd:"22:00", dailyCap:1};
out.push(["ny equal start/end no quiet", g.attempt(ny, at("2026-10-23T03:00:00Z"))]);
out.push(["ny cap 1 same local day", g.attempt(ny, at("2026-10-23T10:00:00Z")).reason]);
// a different gate instance is independent
out.push(["independent gate", createPushGate().attempt(cu, at("2026-10-23T03:00:00Z"))]);
// DST: New York 2026-11-01 01:30 local (ambiguous) and wrap window
const dst = {id:"dst", timeZone:"America/New_York", quietStart:"23:00", quietEnd:"06:30", dailyCap:5};
out.push(["dst wrap quiet 00:30 EDT-> 04:30Z", g.attempt(dst, at("2026-11-01T04:30:00Z"))]);
out.push(["dst wrap 07:00 local allowed", g.attempt(dst, at("2026-11-01T12:00:00Z"))]);
for (const [k,v] of out) console.log(k.padEnd(36), JSON.stringify(v));
'

